<?xml version="1.0" encoding="UTF-8" standalone="no"?>
<mappingRoot xmlns="http://www.ibm.com/2008/ccl/Mapping" xmlns:map="default" domainID="com.ibm.msl.mapping.xml" domainIDExtension="mb" mainMap="true" targetNamespace="default" version="8.0.5.0">
    <input path="/Delimited.xsd"/>
    <output path="jar:file://!com/ibm/etools/mft/map/xsds/predefined/JsonDomainMsg.xsd" var="var1"/>
    <output derivedFrom="MB:JSON_schema_in_json_file" path="/JSONSchema.json" var="var"/>
    <namespaces>
        <namespace kind="supplement" prefix="out" uri="http://www.ibm.com/iib/msl/json"/>
    </namespaces>
    <generation engine="xquery"/>
    <mappingDeclaration name="DelimitedtoJSON_Mapping">
        <input path="mb:msg(MessageDelimited,assembly,DFDL,Properties)" var="ComIbmMessageAssembly_MessageDelimited"/>
        <output namespace="http://www.ibm.com/iib/msl/json" path="$var1/mb:msg(JSON,assembly,JSON,Properties)" var="ComIbmMessageAssembly_JSON">
            <cast derivedFrom="MB:JSON_TYPE" path="$ComIbmMessageAssembly_JSON/JSON/Data/type('anyType')" qualifier="{http://www.ibm.com/iib/msl/json}JSONArray_JSONSchema_JsonType" ref="var"/>
        </output>
        <move>
            <input path="$ComIbmMessageAssembly_MessageDelimited/Properties"/>
            <output path="$ComIbmMessageAssembly_JSON/Properties"/>
        </move>
        <foreach>
            <input path="$ComIbmMessageAssembly_MessageDelimited/MessageDelimited/Item"/>
            <output path="$ComIbmMessageAssembly_JSON/JSON/spath('Data',2)/Item"/>
            <move>
                <input path="LastName"/>
                <output path="LastName"/>
            </move>
            <move>
                <input path="FirstName"/>
                <output path="FirstName"/>
            </move>
            <move>
                <input path="Address"/>
                <output path="Address"/>
            </move>
            <move>
                <input path="DateOfBirth"/>
                <output path="DateOfBirth"/>
            </move>
        </foreach>
    </mappingDeclaration>
</mappingRoot>
